const results = $input.all().map(i => i.json).filter(j => j.url);

if (results.length === 0) {
  return [{ json: { summary_message: "No se encontraron ofertas que coincidan hoy." } }];
}

let message = "🚀 **Nuevas ofertas de trabajo encontradas:** \n\n ";

results.forEach((job, index) => {
  // Limpiamos el título por si trae espacios raros
  const title = job.title ? job.title.trim() : "Oferta de trabajo";
  const url = job.url;

  message += ` ${index + 1}. **${title}** \n 🔗 ${url} \n\n `;
});

return [{
  json: {
    summary_message: message.trim()
  }
}];

// Read the full description of every result and keep only remote roles
// (or on-site/hybrid in Buenos Aires) asking for at most 4 years of experience.
const MAX_YEARS = 4;
const raw = [];
$input.all().forEach(item => {
  if (item.json.results) raw.push(...item.json.results.map(r => ({ title: r.title, url: r.url, text: r.raw_content || r.content || '' })));
  if (item.json.data?.web) raw.push(...item.json.data.web.map(r => ({ title: r.title, url: r.url, text: r.markdown || r.description || '' })));
});

const seen = new Set();
const jobs = raw.filter(j => j.url && !seen.has(j.url) && seen.add(j.url));

const SENIOR_TITLE = /\b(senior|sr\.?|lead|staff|principal|head|manager|director|architect|vp)\b/i;
const REMOTE = /\b(remote|remoto|remota|work from home|anywhere|distributed)\b/i;
const ONSITE = /\b(on-?site|onsite|hybrid|h[ií]brido|presencial|in[- ]office)\b/i;
const BUENOS_AIRES = /buenos aires|\bcaba\b|\bgba\b/i;

// Lowest year count of every "N years of experience" / "N-M years" requirement found
function requiredYears(text) {
  const found = [];
  const re = /(\d{1,2})\s*(?:\+|(?:-|–|to|a)\s*\d{1,2})?\s*\+?\s*(?:years?|yrs?|a[ñn]os)/gi;
  let m;
  while ((m = re.exec(text))) {
    const ctx = text.slice(Math.max(0, m.index - 80), m.index + m[0].length + 80);
    if (/experien|exp\.|background|proven|track record|hands-on/i.test(ctx)) found.push(Number(m[1]));
  }
  return found;
}

// Indeed country subdomains other than Argentina (pk.indeed.com, uk.indeed.com...) are noise
const FOREIGN_INDEED = /^https?:\/\/(?!www\.|ar\.)[a-z]{2}\.indeed\.com/i;

const kept = [];
for (const j of jobs) {
  if (FOREIGN_INDEED.test(j.url)) continue;
  const text = (j.title + '\n' + j.text).slice(0, 60000);
  if (SENIOR_TITLE.test(j.title)) continue;
  if (/\b(senior|sr\.)\s+(level|engineer|developer)/i.test(text.slice(0, 1500))) continue;
  const years = requiredYears(text);
  if (years.length && Math.min(...years) > MAX_YEARS) continue;
  const remote = REMOTE.test(text);
  const onsite = ONSITE.test(text);
  const ba = BUENOS_AIRES.test(text);
  if (!remote && !ba) continue;            // not remote and not in Buenos Aires
  if (!remote && onsite && !ba) continue;
  kept.push({ json: { title: j.title, url: j.url, years: years.join(','), remote, buenosAires: ba } });
}

if (kept.length === 0) return [{ json: { title: '__none__' } }];
return kept;
